corrected_code:
const express = require('express');
const { PrismaClient } = require('@prisma/client');

const prisma = new PrismaClient();
const app = express();

const workspaceApp = express({ mergeParams: true });
const secretsSubRouter = express.Router({ mergeParams: true });

app.use('/workspaces/:workspaceSlug', async (req, res, next) => {
  if (!req.user || !req.user.id) {
    return res.status(401).json({ error: 'Authentication required' });
  }

  const membership = await prisma.workspaceMember.findFirst({
    where: {
      workspace: { slug: req.params.workspaceSlug },
      userId: req.user.id
    },
    include: { workspace: true }
  });

  if (!membership) {
    return res.status(403).json({ error: 'Not a member of this workspace' });
  }

  req.workspace = membership.workspace;
  next();
}, workspaceApp);

workspaceApp.use('/secrets', secretsSubRouter);

secretsSubRouter.get('/:secretId', async (req, res) => {
  // Strictly enforce workspace isolation on the secret object
  const secret = await prisma.vaultSecret.findFirst({
    where: {
      id: req.params.secretId,
      workspaceId: req.workspace.id
    }
  });

  if (!secret) {
    return res.status(404).json({ error: 'Secret not found in this workspace' });
  }

  res.json({ secret });
});

app.listen(3000);
